var secondaryContainer = section.querySelector('.ContentMedia--secondaryContainer--A3hSV');

if (!primaryContainer || !secondaryContainer) return;

var primaryItem = primaryContainer.querySelector('.mediaListItem');
if (!primaryItem) return;

var videoItems = secondaryContainer.querySelectorAll('.mediaListItem');
var firstVideoItem = null;
for (var i = 0; i < videoItems.length; i++) {
  if (videoItems[i].querySelector('.MediaObject--mediaIcon--wFOkX')) {
    firstVideoItem = videoItems[i];
    break;
  }
}

if (!firstVideoItem) return;

primaryItem.style.display = 'none';

var clone = firstVideoItem.cloneNode(true);
clone.style.order = '-1';
secondaryContainer.insertBefore(clone, secondaryContainer.firstChild);

if (element.hasAttribute('autoplay')) return;
element.setAttribute('autoplay', '');
element.setAttribute('muted', '');
element.setAttribute('playsinline', '');
element.autoplay = true;
element.muted = true;

var section = element.closest('section[aria-label="TOP STORY"]');
if (!section) return;

var primaryContainer = section.querySelector('.ContentMedia--primaryContainer--m5y1v');
var secondaryContainer = section.querySelector('.ContentMedia--secondaryContainer--A3hSV');

if (!primaryContainer || !secondaryContainer) return;

// Hide the primary static image
var primaryItem = primaryContainer.querySelector('.mediaListItem');
if (primaryItem) {
  primaryItem.style.display = 'none';
}

// Make secondary container use flex order to put video first
secondaryContainer.style.display = 'flex';
secondaryContainer.style.flexWrap = 'wrap';

var videoItems = secondaryContainer.querySelectorAll('.mediaListItem');
for (var i = 0; i < videoItems.length; i++) {
  var hasVideoIcon = videoItems[i].querySelector('.MediaObject--mediaIcon--wFOkX');
  if (hasVideoIcon && i > 0) {
    videoItems[i].style.order = '-1';
  }
}

var section = element.closest('section[aria-label="TOP STORY"]');
if (!section) return;

var primaryContainer = section.querySelector('.ContentMedia--primaryContainer--m5y1v');
var secondaryContainer = section.querySelector('.ContentMedia--secondaryContainer--A3hSV');

if (!primaryContainer || !secondaryContainer) return;

// Find the first video item in secondary
var videoItems = secondaryContainer.querySelectorAll('.mediaListItem');
var firstVideoItem = null;
for (var i = 0; i < videoItems.length; i++) {
  if (videoItems[i].querySelector('.MediaObject--mediaIcon--wFOkX')) {
    firstVideoItem = videoItems[i];
    break;
  }
}

if (!firstVideoItem) return;

// Hide the static primary item
var primaryItem = primaryContainer.querySelector('.mediaListItem');
if (primaryItem) {
  primaryItem.style.display = 'none';
}

// Clone the video item and insert it into the primary container
var clone = firstVideoItem.cloneNode(true);
clone.classList.remove('smallMedia', 'MediaObject--smallMedia--ttgFl', 'ContentMedia--smallMedia--EjVsJ');
clone.classList.add('fullMedia', 'MediaObject--fullMedia--F7neI', 'ContentMedia--fullMedia--k52SL');

// Clear existing content in primary and add the video
primaryContainer.innerHTML = '';
primaryContainer.appendChild(clone);

if (element.dataset.videoSwapped) return;
element.dataset.videoSwapped = 'true';

var primaryContainer = element.querySelector('.ContentMedia--primaryContainer--m5y1v');
var secondaryContainer = element.querySelector('.ContentMedia--secondaryContainer--A3hSV');

if (!primaryContainer || !secondaryContainer) return;

var secondaryItems = secondaryContainer.querySelectorAll('.mediaListItem');
var videoItem = null;
for (var i = 0; i < secondaryItems.length; i++) {
  if (secondaryItems[i].querySelector('.MediaObject--mediaIcon--wFOkX')) {
    videoItem = secondaryItems[i];
    break;
  }
}

if (!videoItem) return;

var primaryItem = primaryContainer.querySelector('.mediaListItem');
if (primaryItem) {
  primaryItem.style.display = 'none';
}

var clone = videoItem.cloneNode(true);
var cloneLink = clone.querySelector('.mediaLink');
if (cloneLink) {
  cloneLink.classList.remove('smallMedia', 'MediaObject--smallMedia--ttgFl', 'ContentMedia--smallMedia--EjVsJ');
  cloneLink.classList.add('fullMedia', 'MediaObject--fullMedia--F7neI', 'ContentMedia--fullMedia--k52SL');
}
primaryContainer.innerHTML = '';
primaryContainer.appendChild(clone);

var img = clone.querySelector('img');
if (img) {
  img.style.width = '100%';
  img.style.height = '100%';
  img.style.objectFit = 'cover';
}
